import { path } from '@servicenow/sdk-build-core'
import { createTestContext, findInput, getMergedRecordUpdates, loadTestFile, unzipInputArray } from '../test-utils'

/**
 * Example Unit Tests - Part 5
 *
 * This test suite covers 3 example files with comprehensive bidirectional testing:
 * 1. change-request-approval-notification-flow.now.ts - Flow with approval notifications
 * 2. sla-task-excalation-flow.now.ts - Flow with SLA escalation logic
 * 3. third-party-ticket-integration-flow.now.ts - Flow with third-party integration
 *
 * Each file has:
 * - Fluent → XML tests: Verify correct XML generation from TypeScript
 * - XML → Fluent tests: Verify correct TypeScript generation from XML
 *
 * All tests use fixed patterns with no conditional logic.
 */

describe('Example Unit Tests - Part 5', () => {
    const ctx = createTestContext({ rootDir: path.resolve(__dirname, '../project') })
    beforeAll(() => ctx.initialize())
    afterEach(() => ctx.cleanup())
    // ============================================================================
    // TEST FILE 1: change-request-approval-notification-flow.now.ts
    // ============================================================================
    describe('File 1: change-request-approval-notification-flow - Fluent to XML', () => {
        test('Flow with trigger validation', async () => {
            const merged = await getMergedRecordUpdates(
                ctx.createProject(),
                'change-request-approval-notification-flow.now.ts',
                'example-unit-tests/fluent'
            )

            // Verify flow record
            expect(merged['sys_hub_flow']).toBeDefined()
            const flows = merged['sys_hub_flow']
            expect(flows.length).toBeGreaterThanOrEqual(1)

            const flow = flows[0]
            expect(flow).toBeDefined()
            expect(flow.type).toBe('flow')
            expect(flow.run_as).toBeDefined()

            // Verify and validate trigger
            expect(merged['sys_hub_trigger_instance_v2']).toBeDefined()
            const triggerInstances = merged['sys_hub_trigger_instance_v2']
            expect(triggerInstances.length).toBeGreaterThan(0)

            const trigger = triggerInstances[0]
            expect(trigger.trigger_type).toBeDefined()
            expect(trigger.trigger_inputs).toBeDefined()

            // Validate trigger inputs
            const triggerInputs = unzipInputArray(trigger.trigger_inputs)
            const val = (name: string) => findInput(triggerInputs, name)?.value

            expect(val('table')).toBe('change_request')
            expect(val('condition')).toBe('approval=approved')
            expect(val('run_flow_in')).toBe('background')
        })

        test('Action instances with lookUpRecord and sendEmail validations', async () => {
            const merged = await getMergedRecordUpdates(
                ctx.createProject(),
                'change-request-approval-notification-flow.now.ts',
                'example-unit-tests/fluent'
            )

            // Verify action instances
            expect(merged['sys_hub_action_instance_v2']).toBeDefined()
            const actionInstances = merged['sys_hub_action_instance_v2']
            expect(actionInstances.length).toBeGreaterThan(0)

            // Find and validate log action with datapills
            const logAction = actionInstances.find(
                (action: any) => action.comment === 'Log change request approval detected'
            )
            expect(logAction).toBeDefined()

            const logInputsArr = unzipInputArray(logAction.values)
            const logInputs = (name: string) => findInput(logInputsArr, name)?.value

            expect(logInputs('log_level')).toBe('info')
            // Verify log_message contains datapill: {{uuid.number}}
            const logMessage = logInputs('log_message')
            expect(logMessage).toContain('has been approved')
            expect(logMessage).toMatch(/\{\{[^}]+\.number\}\}/)
            expect(logMessage).toContain('number')

            // Find and validate lookUpRecord action for requester with datapills
            const lookupRequesterAction = actionInstances.find(
                (action: any) => action.comment === 'Retrieve requester information'
            )
            expect(lookupRequesterAction).toBeDefined()

            const requesterInputsArr = unzipInputArray(lookupRequesterAction.values)
            const requesterInputs = (name: string) => findInput(requesterInputsArr, name)?.value

            expect(requesterInputs('table')).toBe('sys_user')
            // Verify conditions contain datapill: {{uuid.requested_by}}
            const requesterConditions = requesterInputs('conditions')
            expect(requesterConditions).toContain('sys_id=')
            expect(requesterConditions).toMatch(/\{\{[^}]+\.requested_by\}\}/)
            expect(requesterConditions).toContain('requested_by')
        })
    })

    describe('File 1: change-request-approval-notification-flow - XML to Fluent', () => {
        test('Flow with approval notifications transforms correctly from XML', async () => {
            const project = ctx.createProject()

            const xmlContent = loadTestFile(
                'sys_hub_flow_e022071d9b8a4e81a1c8023e6f2f4e7f.xml',
                'example-unit-tests/xml'
            )
            const { changedFiles } = await project.transform({
                path: 'sys_hub_flow_e022071d9b8a4e81a1c8023e6f2f4e7f.xml',
                content: xmlContent,
            })

            expect(changedFiles).toHaveLength(1)
            const content = changedFiles[0].getContent()

            // Verify imports
            expect(content).toContain('import {')
            expect(content).toContain('Flow')
            expect(content).toContain('trigger')
            expect(content).toContain('action')

            // Verify flow definition
            expect(content).toContain('Flow(')

            // Verify trigger
            expect(content).toContain('trigger.')
            expect(content).toContain('wfa.trigger(')

            // Verify actions
            expect(content).toContain('wfa.action(')
            expect(content).toContain('action.')

            // Verify annotations
            expect(content).toContain('annotation:')
        })
    })

    // ============================================================================
    // TEST FILE 2: sla-task-excalation-flow.now.ts
    // ============================================================================
    describe('File 2: sla-task-excalation-flow - Fluent to XML', () => {
        test('Flow with SLA trigger validation', async () => {
            const merged = await getMergedRecordUpdates(
                ctx.createProject(),
                'sla-task-excalation-flow.now.ts',
                'example-unit-tests/fluent'
            )

            // Verify flow record
            expect(merged['sys_hub_flow']).toBeDefined()
            const flows = merged['sys_hub_flow']
            expect(flows.length).toBeGreaterThanOrEqual(1)

            const flow = flows[0]
            expect(flow).toBeDefined()
            expect(flow.type).toBe('flow')
            expect(flow.run_as).toBeDefined()

            // Verify trigger (SLA task trigger has no inputs)
            expect(merged['sys_hub_trigger_instance_v2']).toBeDefined()
            const triggerInstances = merged['sys_hub_trigger_instance_v2']
            expect(triggerInstances.length).toBeGreaterThan(0)

            const trigger = triggerInstances[0]
            expect(trigger.trigger_type).toBeDefined()
            expect(trigger.trigger_inputs).toBeDefined()
        })

        test('Action instances with lookUpRecord and updateRecord validations', async () => {
            const merged = await getMergedRecordUpdates(
                ctx.createProject(),
                'sla-task-excalation-flow.now.ts',
                'example-unit-tests/fluent'
            )

            // Verify action instances
            expect(merged['sys_hub_action_instance_v2']).toBeDefined()
            const actionInstances = merged['sys_hub_action_instance_v2']
            expect(actionInstances.length).toBeGreaterThan(0)

            // Verify flow logic instances
            expect(merged['sys_hub_flow_logic_instance_v2']).toBeDefined()
            const flowLogicInstances = merged['sys_hub_flow_logic_instance_v2']
            expect(flowLogicInstances.length).toBeGreaterThan(0)

            // Find and validate lookUpRecord action for SLA record
            const lookupSLAAction = actionInstances.find(
                (action: any) => action.comment === 'Retrieve SLA record to get task reference'
            )
            expect(lookupSLAAction).toBeDefined()

            const slaInputsArr = unzipInputArray(lookupSLAAction.values)
            const slaInputs = (name: string) => findInput(slaInputsArr, name)?.value

            expect(slaInputs('table')).toBe('task_sla')
            expect(slaInputs('conditions')).toContain('sys_id=')

            // Find and validate lookUpRecord action for task record
            const lookupTaskAction = actionInstances.find(
                (action: any) => action.comment === 'Retrieve task record at 75% SLA'
            )
            expect(lookupTaskAction).toBeDefined()

            const taskInputsArr = unzipInputArray(lookupTaskAction.values)
            const taskInputs = (name: string) => findInput(taskInputsArr, name)?.value

            expect(taskInputs('table')).toBe('task')
            expect(taskInputs('conditions')).toContain('sys_id=')
        })
    })

    describe('File 2: sla-task-excalation-flow - XML to Fluent', () => {
        test('Flow with SLA escalation transforms correctly from XML', async () => {
            const project = ctx.createProject()

            const xmlContent = loadTestFile(
                'sys_hub_flow_38a5631c64874463808d678ddef0461f.xml',
                'example-unit-tests/xml'
            )
            const { changedFiles } = await project.transform({
                path: 'sys_hub_flow_38a5631c64874463808d678ddef0461f.xml',
                content: xmlContent,
            })

            expect(changedFiles).toHaveLength(1)
            const content = changedFiles[0].getContent()

            // Verify imports
            expect(content).toContain('import {')
            expect(content).toContain('Flow')
            expect(content).toContain('trigger')
            expect(content).toContain('action')

            // Verify flow definition
            expect(content).toContain('Flow(')

            // Verify trigger
            expect(content).toContain('trigger.')
            expect(content).toContain('wfa.trigger(')

            // Verify actions
            expect(content).toContain('wfa.action(')
            expect(content).toContain('action.')

            // Verify annotations
            expect(content).toContain('annotation:')
        })
    })

    // ============================================================================
    // TEST FILE 3: third-party-ticket-integration-flow.now.ts
    // ============================================================================
    describe('File 3: third-party-ticket-integration-flow - Fluent to XML', () => {
        test('Flow with trigger validation', async () => {
            const merged = await getMergedRecordUpdates(
                ctx.createProject(),
                'third-party-ticket-integration-flow.now.ts',
                'example-unit-tests/fluent'
            )

            // Verify flow record
            expect(merged['sys_hub_flow']).toBeDefined()
            const flows = merged['sys_hub_flow']
            expect(flows.length).toBeGreaterThanOrEqual(1)

            const flow = flows[0]
            expect(flow).toBeDefined()
            expect(flow.type).toBe('flow')
            expect(flow.run_as).toBeDefined()

            // Verify and validate trigger
            expect(merged['sys_hub_trigger_instance_v2']).toBeDefined()
            const triggerInstances = merged['sys_hub_trigger_instance_v2']
            expect(triggerInstances.length).toBeGreaterThan(0)

            const trigger = triggerInstances[0]
            expect(trigger.trigger_type).toBeDefined()
            expect(trigger.trigger_inputs).toBeDefined()

            // Validate inbound email trigger inputs
            const triggerInputs = unzipInputArray(trigger.trigger_inputs)
            const val = (name: string) => findInput(triggerInputs, name)?.value

            expect(val('email_conditions')).toContain('subject')
            expect(val('target_table')).toBe('incident')
            expect(val('order')).toBe(100)
        })

        test('Action instances with log and updateRecord validations', async () => {
            const merged = await getMergedRecordUpdates(
                ctx.createProject(),
                'third-party-ticket-integration-flow.now.ts',
                'example-unit-tests/fluent'
            )

            // Verify action instances
            expect(merged['sys_hub_action_instance_v2']).toBeDefined()
            const actionInstances = merged['sys_hub_action_instance_v2']
            expect(actionInstances.length).toBeGreaterThan(0)

            // Verify flow logic instances
            expect(merged['sys_hub_flow_logic_instance_v2']).toBeDefined()
            const flowLogicInstances = merged['sys_hub_flow_logic_instance_v2']
            expect(flowLogicInstances.length).toBeGreaterThan(0)

            // Find and validate log action for request received
            const logAction = actionInstances.find(
                (action: any) => action.comment === 'Log inbound request from third-party system'
            )
            expect(logAction).toBeDefined()

            const logInputsArr = unzipInputArray(logAction.values)
            const logInputs = (name: string) => findInput(logInputsArr, name)?.value

            expect(logInputs('log_level')).toBe('info')
            expect(logInputs('log_message')).toContain('Received inbound request from third-party system')

            // Find and validate createRecord action for incident
            const createIncidentAction = actionInstances.find(
                (action: any) => action.comment === 'Create incident from third-party request'
            )
            expect(createIncidentAction).toBeDefined()

            const createInputsArr = unzipInputArray(createIncidentAction.values)
            const createInputs = (name: string) => findInput(createInputsArr, name)?.value

            expect(createInputs('table_name')).toBe('incident')
            expect(createInputs('values')).toContain('priority')
        })
    })

    describe('File 3: third-party-ticket-integration-flow - XML to Fluent', () => {
        test('Flow with third-party integration transforms correctly from XML', async () => {
            const project = ctx.createProject()

            const xmlContent = loadTestFile(
                'sys_hub_flow_0574520bccfb4af688b13b5cc57fce96.xml',
                'example-unit-tests/xml'
            )
            const { changedFiles } = await project.transform({
                path: 'sys_hub_flow_0574520bccfb4af688b13b5cc57fce96.xml',
                content: xmlContent,
            })

            expect(changedFiles).toHaveLength(1)
            const content = changedFiles[0].getContent()

            // Verify imports
            expect(content).toContain('import {')
            expect(content).toContain('Flow')
            expect(content).toContain('trigger')
            expect(content).toContain('action')

            // Verify flow definition
            expect(content).toContain('Flow(')

            // Verify trigger
            expect(content).toContain('trigger.')
            expect(content).toContain('wfa.trigger(')

            // Verify actions
            expect(content).toContain('wfa.action(')
            expect(content).toContain('action.')

            // Verify annotations
            expect(content).toContain('annotation:')
        })
    })
})
